const kzLessons = [{"id": "kazakhstan-1", "title": "Казахстан на карте", "text": "Казахстан — девятая по площади страна мира (около 2,7 млн км²) и самая большая страна без выхода к океану. Он лежит в Азии и небольшой частью в Европе — к западу от реки Урал. Столица — Астана.", "questions": [{"q": "Какое место по площади занимает Казахстан среди стран мира?", "options": ["3-е", "9-е", "15-е"], "answer": 1, "why": "Площадь — около 2,7 млн км²."}, {"q": "С какой страной у Казахстана самая длинная граница?", "options": ["Россия", "Китай", "Узбекистан"], "answer": 0, "why": "Граница с Россией — более 7 500 км."}, {"type": "tf", "q": "Казахстан имеет выход к Мировому океану.", "options": ["Верно", "Неверно"], "answer": 1, "why": "Каспийское и Аральское — внутренние водоёмы, выхода к океану нет."}, {"q": "Сколько стран граничит с Казахстаном?", "options": ["3", "5", "7"], "answer": 1, "why": "Россия, Китай, Кыргызстан, Узбекистан и Туркменистан."}, {"q": "Как называется столица Казахстана?", "options": ["Алматы", "Шымкент", "Астана"], "answer": 2, "why": "Астана — столица с 1997 года."}]}, {"id": "kazakhstan-2", "title": "Реки, озёра и моря", "text": "Крупнейшие реки Казахстана — Иртыш, Урал, Сырдарья и Ишим. На западе лежит Каспийское море, на юго-западе когда-то было Аральское. Озеро Балхаш необычно: его западная часть пресная, восточная — солёная.", "questions": [{"q": "Какое озеро наполовину пресное, наполовину солёное?", "options": ["Балхаш", "Байкал", "Ладожское"], "answer": 0, "why": "Узкий пролив делит Балхаш на две части с разной солёностью."}, {"q": "Какое море омывает Казахстан на западе?", "options": ["Каспийское", "Чёрное", "Балтийское"], "answer": 0, "why": "Казахстан — одна из прикаспийских стран."}, {"q": "Какая река течёт из Китая через Казахстан в Россию?", "options": ["Волга", "Днепр", "Иртыш"], "answer": 2, "why": "Иртыш — главный приток Оби."}, {"type": "tf", "q": "Аральское море сильно обмелело из-за забора воды на орошение.", "options": ["Верно", "Неверно"], "answer": 0, "why": "Реки Амударья и Сырдарья разобрали на поля."}, {"q": "Какая река впадает в Каспийское море?", "options": ["Урал", "Ишим", "Или"], "answer": 0, "why": "Урал течёт с южного Урала до Каспия."}]}, {"id": "kazakhstan-3", "title": "Города и столица", "text": "Астана стоит на реке Ишим. Крупнейший город страны — Алматы, бывшая столица до 1997 года. Шымкент — третий по значению мегаполис, Актау — порт на Каспии, Караганда — угольный центр.", "questions": [{"q": "Какой город — крупнейший в Казахстане?", "options": ["Астана", "Алматы", "Актобе"], "answer": 1, "why": "В Алматы живёт около 2 млн человек."}, {"q": "Откуда столицу перенесли в 1997 году?", "options": ["Из Караганды", "Из Шымкента", "Из Алматы"], "answer": 2, "why": "Тогда Алма-Ату сменила Акмола, позже ставшая Астаной."}, {"q": "Какой город — главный порт Казахстана на Каспии?", "options": ["Актау", "Атырау", "Павлодар"], "answer": 0, "why": "Актау стоит на полуострове Мангистау."}, {"type": "tf", "q": "Астана расположена на реке Ишим.", "options": ["Верно", "Неверно"], "answer": 0, "why": "Ишим протекает через центр столицы."}, {"q": "Какой город — центр угледобычи?", "options": ["Туркестан", "Кызылорда", "Караганда"], "answer": 2, "why": "Карагандинский бассейн — один из главных угольных районов."}]}, {"id": "kazakhstan-4", "title": "Природа и рельеф", "text": "Основная часть страны — равнины: степи на севере, полупустыни и пустыни на юге. На востоке поднимается Алтай, на юго-востоке — Тянь-Шань. Климат резко континентальный: холодная зима и жаркое лето.", "questions": [{"q": "Какая горная система находится на юго-востоке Казахстана?", "options": ["Тянь-Шань", "Кавказ", "Анды"], "answer": 0, "why": "Заилийский Алатау — северный хребет Тянь-Шаня над Алматы."}, {"q": "Какая природная зона преобладает на севере страны?", "options": ["Степь", "Тайга", "Тундра"], "answer": 0, "why": "Казахстанская степь — часть Великой степи Евразии."}, {"q": "Как называют климат Казахстана?", "options": ["Резко континентальный", "Морской", "Субтропический"], "answer": 0, "why": "Большие перепады температур между зимой и летом."}, {"type": "tf", "q": "На востоке Казахстана расположены горы Алтай.", "options": ["Верно", "Неверно"], "answer": 0, "why": "Рудный Алтай — один из горнорудных районов."}, {"q": "Какая пустыня есть в Казахстане?", "options": ["Сахара", "Бетпак-Дала", "Гоби"], "answer": 1, "why": "Бетпак-Дала лежит в центре страны."}]}, {"id": "kazakhstan-5", "title": "Регионы страны", "text": "Казахстан делится на области и города республиканского значения. Мангистау — нефть и Каспий, Костанай и Акмолинская область — зерно, Восточный Казахстан — металлургия, Туркестан — древний город с мавзолеем Ходжи Ахмеда Ясави.", "questions": [{"q": "В каком городе находится мавзолей Ходжи Ахмеда Ясави?", "options": ["Астана", "Туркестан", "Актау"], "answer": 1, "why": "Мавзолей входит в список Всемирного наследия ЮНЕСКО."}, {"q": "Какая область на Каспии известна нефтью?", "options": ["Мангистауская", "Костанайская", "Акмолинская"], "answer": 0, "why": "Центр области — Актау."}, {"q": "Где выращивают основную часть зерна?", "options": ["На севере страны", "На юге, в горах", "В пустынях"], "answer": 0, "why": "Зерновой пояс — Костанайская, Акмолинская, Северо-Казахстанская области."}, {"type": "tf", "q": "Усть-Каменогорск стоит на реке Иртыш.", "options": ["Верно", "Неверно"], "answer": 0, "why": "Это центр цветной металлургии востока страны."}, {"q": "Как называется космодром Казахстана, арендуемый Россией?", "options": ["Байконур", "Плесецк", "Восточный"], "answer": 0, "why": "Отсюда стартовал Юрий Гагарин в 1961 году."}]}, {"id": "kazakhstan-6", "title": "Ресурсы и хозяйство", "text": "Казахстан — мировой лидер по добыче урана, крупный экспортёр нефти, угля, меди, хрома и зерна. Нефтяные месторождения — Тенгиз, Кашаган и Карачаганак. Денежная единица — тенге.", "questions": [{"q": "По добыче какого металла Казахстан — первый в мире?", "options": ["Золото", "Алюминий", "Уран"], "answer": 2, "why": "Около 40% мирового урана."}, {"q": "Как называется крупное нефтяное месторождение на шельфе Каспия?", "options": ["Самотлор", "Кашаган", "Ромашкино"], "answer": 1, "why": "Кашаган — одно из крупнейших морских месторождений."}, {"q": "Как называется денежная единица Казахстана?", "options": ["Тенге", "Рубль", "Манат"], "answer": 0, "why": "Тенге введён в 1993 году."}, {"type": "tf", "q": "Пшеница — одна из главных зерновых культур Казахстана.", "options": ["Верно", "Неверно"], "answer": 0, "why": "Страна — крупный экспортёр пшеницы и муки."}, {"q": "Какое месторождение нефти находится в Атырауской области?", "options": ["Уренгой", "Приобское", "Тенгиз"], "answer": 2, "why": "Тенгиз — одно из глубочайших нефтяных месторождений мира."}]}]
