export const topics = [...base, mapTopic, capTopic, kzTopic].map((t) => ({ ...t, lessons: [t.lesson, ...extra[t.id]] }))
export const findLesson = (id) => {
  for (const t of topics) { const l = t.lessons.find((x) => x.id === id); if (l) return { ...l, icon: t.icon, color: t.color } }
}
export const totalLessons = topics.reduce((a, t) => a + t.lessons.length, 0)

