// Ежедневный вызов: 5 вопросов, набор зависит от даты
const hashStr = (s) => [...s].reduce((h, c) => (h * 31 + c.charCodeAt(0)) | 0, 0)
export const dailyLesson = (date) => ({
  id: `daily-${date}`, title: 'Ежедневный вызов', icon: 'zap', color: '#16a34a',
  text: 'Пять вопросов из разных тем. Новый набор каждый день.',
  questions: topics.flatMap((t) => t.lessons.flatMap((l) => l.questions))
    .filter((q) => !q.type || !['map', 'mapid'].includes(q.type))
    .map((q) => [hashStr(date + q.q), q]).sort((a, b) => a[0] - b[0]).slice(0, 5).map((x) => varyQuestion(x[1])),
})
